"""Self-contained committed adapter: embedded exact bytes, no pip/GitHub download."""
import base64,hashlib,json,os
from pathlib import Path,PurePosixPath
import sys,zlib
SOURCE_FILES = {'src/torchoed/__init__.py': 'd04e9e889ff8928047b86b2938e51eccea4fef6934ee63cf8f004238906e4585', 'src/torchoed/_smoke.py': 'b5e6eccd3384d6cf727ae3d0f075ae2064aacb35c96309a339e7493ae5c5fbca', 'src/torchoed/_validation.py': '78e2981a0b6a91d9a6e666c47265b3c9c07ab18402b21a79a56964d1f78d31ff', 'src/torchoed/criteria.py': '6df707495530475222620ab23f22eed705b3cbfa5c56f9d344f67bb3a78c0fc1', 'src/torchoed/exchange.py': 'b139fa8b182c4c205fa2c5dc07dcc4b1c6431a9291314da942a0d5c71787eed8', 'src/torchoed/factorial.py': '513ff4c7332b8e8ccecc130009e2918fc7508fd91f5feb0d814fffd16db0c8f4', 'src/torchoed/features.py': '0807d767cc1d1eb255c24911aa3674e9998e550c87a91f428c016b902efdedd3', 'src/torchoed/information.py': '96b04634afee837446a3bd66f0354e474375d07597b2a58f718ae778b09ba598', 'src/torchoed/sampling.py': '7f9cf08087749fdc1792b508710807230e619e4b23fe26a72b6ead11b66bd48f', 'src/torchoed/two_swap.py': 'efbca817a7ef2d30225ff2e30ce2bd140a59725b224a4d72c164dd6a83a2a468', 'tests/oracle_two_swap.py': 'b28272a5c17bb4f5a6a81ce24835b10b271695e5ddcb78e4e1bf5a0b791865f2', 'tests/oracle_exchange.py': 'a1d8ba05b46e21d121738d0b958e1ac00a679d7f977559dd8a853ae3558bca59', 'LICENSE': '2f0819452dd5f7667e2c0e93b769238a41c8164e62f89f212646076f66765bde', 'experiments/m3b2p0/gather_scores.py': 'ef100c10e999316ca22616c9e634d005c8ad363c29103f7c0d10676ac4d18083', 'experiments/m3b2p0/run_probe.py': '0934cd001ee09af76910fdd07b2e55a77c8354311ddc2d6cc318f5eec495f635'}
PAYLOAD = ''

def main():
    sha=os.environ['SAE_CANDIDATE_SHA']
    root=Path('/content')/('torchoed13-'+sha[:12])
    root.mkdir(exist_ok=False)
    data=json.loads(zlib.decompress(base64.b64decode(PAYLOAD)))
    for name,encoded in data.items():
        path=PurePosixPath(name)
        assert not path.is_absolute() and '..' not in path.parts
        raw=base64.b64decode(encoded)
        assert hashlib.sha256(raw).hexdigest()==SOURCE_FILES[name]
        target=root/name;target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes(raw)
    sys.dont_write_bytecode=True
    sys.path.insert(0,str(root/'experiments/m3b2p0'))
    import torch
    import run_probe
    for dtype,gates,name in [('float64',['P1','P3','P6'],'gpu_fp64.json'),('float32',['P6'],'gpu_fp32.json')]:
        try:
            if not torch.cuda.is_available():
                report=dict(status='BLOCKED',reason='torch.cuda.is_available() is false',device='NOT_OBSERVED')
            else:
                report=run_probe.run(gates,'cuda',dtype,sha,threads=2,output='/content/probe-progress.json')
        except Exception as exc:
            import traceback
            report=dict(status='FAIL',error=repr(exc),traceback=traceback.format_exc())
        artifact=dict(source_sha=sha,status='PASS',claim='PROBE_ONLY_TRANSPORT_COMPLETED_SCIENCE_UNREVIEWED',
                      scientific_status=report['status'],probe=report,embedded_code_sha256=SOURCE_FILES)
        raw=(json.dumps(artifact,indent=2,allow_nan=False)+'\n').encode()
        assert len(raw)<=1048576
        (Path('/content')/name).write_bytes(raw)
        print('ARTIFACT',name,len(raw),hashlib.sha256(raw).hexdigest(),flush=True)

if __name__=='__main__':
    main()
